arguments.source:
basis e {}
f(a: u1, b: u1) = a & b
gates f basis e

basis a { inv(x) = ~x }
basis b : a { andp(x, y) = x & y }
basis a : b { orp(x, y) = x | y }
f(a: u1, b: u1) = a | b
gates f basis a

basis c256 { t(x, y) = lut cost 256 }
f(a: u1, b: u1) = a & b
gates f basis c256

basis n1 { t(x, y) = lut cost -1 }
f(a: u1, b: u1) = a & b
gates f basis n1

basis one { inv(x) = ~x }
f(a: u1) = ~a
gates f basis one

basis g1 { t(x, y) = lut 255 }
f(a: u1, b: u1) = a & b
gates f basis g1

basis inc { g(x, y) = x & y }
f(a: u1, b: u1) = a & b
gates f basis inc
